import sys
sys.path.insert(0, '/Users')
import roman
to_roman = roman.to_roman

expect = {1:"I",2:"II",3:"III",4:"IV",5:"V",8:"VIII",9:"IX",10:"X",14:"XIV",
          40:"XL",44:"XLIV",49:"XLIX",50:"L",90:"XC",99:"XCIX",100:"C",
          400:"CD",444:"CDXLIV",500:"D",900:"CM",990:"CMXC",1000:"M",
          1987:"MCMLXXXVII",2024:"MMXXIV",3999:"MMMCMXCIX"}
for n,e in expect.items():
    got = to_roman(n)
    assert got == e, (n, got, e)
print("spot checks OK")

vals = [(1000,"M"),(900,"CM"),(500,"D"),(400,"CD"),(100,"C"),(90,"XC"),
        (50,"L"),(40,"XL"),(10,"X"),(9,"IX"),(5,"V"),(4,"IV"),(1,"I")]
def decode(s):
    i=0; total=0
    while i < len(s):
        for v,sy in vals:
            if s.startswith(sy,i):
                total+=v; i+=len(sy); break
        else:
            raise ValueError("bad symbol stream: "+s)
    return total

for n in range(1,4000):
    r = to_roman(n)
    assert decode(r)==n, (n,r)
    assert all(r.count(c)<=3 for c in "IXCM"), (n,r)
print("1..3999 all valid and round-trip")

for bad in (0,-1,4000,4001):
    try:
        to_roman(bad); print("FAIL no raise", bad)
    except ValueError as e:
        print("%s: ValueError(%s)" % (bad, e))
